'use strict';

// The hosted private gateway supplies backend credentials. No secrets enter this bundle.
let backendConnection='connecting', backendMetrics=null, backendEvaluation=null, backendError='', mutationBusy=false;
let demoClientId;
try{demoClientId=localStorage.getItem('upi-guard-workspace')||crypto.randomUUID();localStorage.setItem('upi-guard-workspace',demoClientId);}catch{demoClientId=crypto.randomUUID();}
const originalRender=render;
render=function(){originalRender();const main=$('#main');if(!main)return;const note=document.createElement('div');note.className='service-status '+backendConnection;note.setAttribute('role','status');note.innerHTML=backendConnection==='connected'?`${icon('checkCircle')}<span>${t('Payment checks online · Synthetic demo data','भुगतान जाँच ऑनलाइन · डेमो डेटा')}${backendMetrics?.ephemeral_storage?t(' · Demo history may reset when the service restarts.',' · सेवा दोबारा शुरू होने पर डेमो इतिहास मिट सकता है।'):''}</span>`:backendConnection==='connecting'?`${icon('clock')}<span>${t('Connecting to payment checks…','भुगतान जाँच से जुड़ रहे हैं…')}</span>`:`${icon('alert')}<span>${t('Payment checks are temporarily unavailable. No assessment will be invented.','भुगतान जाँच अभी उपलब्ध नहीं है। कोई अनुमानित परिणाम नहीं दिखाया जाएगा।')}</span><button class="text-link" data-action="retry-backend">${t('Retry','फिर कोशिश करें')}</button>`;main.prepend(note);};

async function api(path,method='GET',body){
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),30000);
 try{const response=await fetch(path,{method,signal:controller.signal,credentials:'same-origin',headers:{'Content-Type':'application/json','X-Demo-Client-ID':demoClientId},...(body===undefined?{}:{body:JSON.stringify(body)})});
  const data=await response.json().catch(()=>null);
  if(!response.ok||!data){const detail=data?.detail;const message=typeof detail==='string'?detail:detail?.message||data?.message||(response.status===503?'Backend service is not configured or is starting up.':'The payment service could not complete this request.');const error=new Error(message);error.status=response.status;throw error;}
  return data;
 }catch(error){if(error.name==='AbortError')throw new Error('The service took too long. Please try again.');if(error instanceof TypeError)throw new Error('Could not reach the payment service. Please try again.');throw error;}finally{clearTimeout(timeout);}
}
async function refreshBackend(repaint=true){
 try{const [activity,metrics,evaluation]=await Promise.all([api('/assessments'),api('/metrics'),api('/evaluation-results').catch(()=>null)]);state.records=activity.records;state.candidate=activity.candidate_ready?'prepared':'none';backendMetrics=metrics;backendEvaluation=evaluation;backendConnection='connected';backendError='';persist();if(repaint)render();return true;}catch(error){backendConnection='unavailable';backendError=error.message;if(repaint)render();return false;}
}
async function mutate(task){if(mutationBusy)return;mutationBusy=true;try{await task();}catch(error){toast(error.message);}finally{mutationBusy=false;}}
function scorePayload(){return {payment_id:flow.paymentId||(flow.paymentId=crypto.randomUUID()),session_id:flow.session,amount:flow.amount,currency:flow.currency,recipient:flow.recipient,recipient_account:flow.account,expected_recipient:flow.expected,message:flow.message,user_intent:flow.intent||null,screen_sharing:flow.id==='remote'&&!flow.stoppedSharing?1:0,device_novelty:0,prior_recipient_count:['merchant','change'].includes(flow.id)&&!flow.changed?3:0,interaction_time_seconds:12,scenario:flow.id,purpose:flow.purpose};}
analyse=async function(){
 if(mutationBusy)return;
 if(!flow){formError=t('Choose a demo payment first.','पहले एक डेमो भुगतान चुनें।');render();return;}
 if(!flow.message.trim()&&!flow.intent){missingContext=true;formError=t('Choose what you are trying to do.','चुनें कि आप क्या करना चाहते हैं।');render();return;}
 missingContext=false;const snapshot=binding(flow),token=++run;flowStep='loading';render();mutationBusy=true;
 try{const result=await api('/score-payment','POST',scorePayload());if(token!==run||!flow||snapshot!==binding(flow))return;
  flow.ref={0:'match',2:'match',1:'mismatch',3:'unavailable'}[result.merchant_status];flow.reference=result.merchant_reference;
  const refund=result.category==='Refund deception';
  assessment={risk:result.risk_tier,category:result.category==='Remote access risk'?'Remote access':result.category,evidence:result.observed_facts.concat(result.inferred_facts),refund,binding:binding(flow),recordId:result.assessment_id,paymentId:result.payment_id,token:result.assessment_token,response:result};
  state.records=[result.record,...state.records.filter(r=>r.id!==result.record.id)];persist();backendConnection='connected';flowStep=refund&&result.risk_tier==='high'?'intent':'result';formError='';render();if(state.readAloud&&flowStep==='result')readAloud();
  // Refresh derived operational values without changing the active payment screen.
  api('/metrics').then(metrics=>{backendMetrics=metrics;}).catch(()=>{});
 }catch(error){if(token===run){flowStep='input';formError=error.message;backendConnection='unavailable';render();}}finally{mutationBusy=false;}
};
updateAction=async function(action){if(!assessment?.recordId)throw new Error('Run a payment check first.');await api('/assessment-action','POST',{assessment_id:assessment.recordId,user_action:action});const record=state.records.find(r=>r.id===assessment.recordId);if(record){record.action=action;if(action==='Recheck required')record.invalidated=true;}persist();};
review=async function(status){const id=selectedRecord;if(!id)return;await mutate(async()=>{await api('/review-label','POST',{assessment_id:id,review_status:status,rationale:'Reviewed in the connected analyst workspace.'});await refreshBackend();toast('Analyst decision saved to the backend audit store.');});};
doChange=async function(){if(!flow)return;await mutate(async()=>{await updateAction('Recheck required');if(assessment)assessment.invalidated=true;flow.oldRecipient=flow.recipient;flow.recipient='Amit Personal';flow.account='amitpersonal@demo';flow.ref='mismatch';flow.reference='Saved destination: sharmamedical@demo';flow.changed=true;flowStep='changed';render();window.scrollTo(0,0);});};

actions['retry-backend']=()=>{backendConnection='connecting';render();refreshBackend();};
actions['cancel-payment']=()=>mutate(async()=>{await updateAction('Cancelled');flow.outcome='Cancelled';flowStep='complete';await refreshBackend(false);render();window.scrollTo(0,0);});
actions['complete-payment']=()=>mutate(async()=>{
 if(!validAssessment()||assessment.risk!=='low')throw new Error('A current assessment with no strong risk indicators is required.');
 try{await api('/confirm-demo-payment','POST',{assessment_id:assessment.recordId,payment_id:assessment.paymentId,session_id:flow.session,amount:flow.amount,currency:flow.currency,recipient:flow.recipient,recipient_account:flow.account,assessment_token:assessment.token});}
 catch(error){if(error.status===409){assessment.invalidated=true;flowStep='changed';render();}throw error;}
 const record=state.records.find(r=>r.id===assessment.recordId);if(record)record.action='Simulated completion';flow.outcome='Simulated completion';flowStep='complete';await refreshBackend(false);render();window.scrollTo(0,0);
});
actions['leave-review']=()=>mutate(async()=>{await updateAction('Reviewed');await refreshBackend(false);navigate('home');toast('Check saved to the backend review queue.');});
actions['change-recipient']=doChange;
actions['reassess']=()=>analyse();
actions['review-fraudulent']=()=>review('Fraudulent');actions['review-legitimate']=()=>review('Legitimate');actions['review-investigate']=()=>review('Needs investigation');
actions['reset']=()=>mutate(async()=>{await api('/demo-data','DELETE');run++;state=seed();state.records=[];state.candidate='none';persist();flow=null;assessment=null;selectedRecord=null;flowStep='input';closeModal();await refreshBackend(false);render();toast('This demo workspace has been reset on the backend.');});
actions['confirm-reset']=()=>openModal(t('Reset this demo workspace?','यह डेमो कार्यक्षेत्र रीसेट करें?'),t('Clears your server-backed checks and decisions.','सर्वर पर सेव आपकी जाँच और फैसले हटेंगे।'),`<p style="font-size:12px;color:var(--muted)">Deletes the checks, review decisions, and candidate selection for your current demo workspace. Other workspaces are unaffected.</p><div class="button-row">${btn('Keep my data','close-modal','secondary')}${btn('Reset demo workspace','reset','danger')}</div>`);
actions['prepare-candidate']=()=>openModal('Prepare a candidate comparison','Use the existing trained candidate artifact; no new training.',`<p style="font-size:12px;color:var(--muted);line-height:1.8">Review and label a case first. The backend will select the supplied candidate model for comparison with its offline evaluation artifact. This does not deploy or retrain a model.</p><div class="button-row">${btn('Prepare comparison','confirm-candidate','','lab')}</div>`);
actions['confirm-candidate']=()=>mutate(async()=>{const result=await api('/pattern-lab/prepare-candidate','POST',{});state.candidate='prepared';persist();closeModal();await refreshBackend(false);navigate('evaluation');toast(result.message);});
actions['pattern-examples']=()=>{const examples=state.records.filter(r=>r.scenario==='job');openModal('Review job-deposit examples','Cases returned by the backend audit store.',examples.length?`<div class="scenario-list">${examples.map(r=>`<button class="scenario-option" data-investigate="${r.id}"><span class="number">${icon('briefcase')}</span><span><strong>${esc(r.recipient)} · ${money(r.amount)}</strong><small>${esc(r.message)}<br>Review: ${esc(r.review)}</small></span>${icon('chevron')}</button>`).join('')}</div>`:`<div class="empty"><h2>No job-deposit cases yet.</h2><p>Run a consumer scenario to create a real backend assessment.</p>${btn('Try job-deposit scenario','start-job')}</div>`);};
actions['start-job']=()=>{view='consumer';mode='request';createFlow('job');};

// Invalidation reaches the service before edited details can receive a new assessment.
actions['edit-details']=()=>{if(!flow)return;openModal('Edit demo payment details','Changes invalidate the server assessment.',`<form id="backend-edit-form"><label class="field-label" for="edit-amount">Amount (INR)</label><input id="edit-amount" name="amount" type="number" min="1" max="1000000" step="0.01" required value="${flow.amount}"><div class="form-row"><label class="field-label" for="edit-recipient">Recipient</label><select id="edit-recipient" name="account"><option value="${esc(flow.account)}">${esc(flow.recipient)} · ${esc(flow.account)}</option>${flow.account!=='sharmamedical@demo'?'<option value="sharmamedical@demo">Sharma Medical · sharmamedical@demo</option>':''}${flow.account!=='amitpersonal@demo'?'<option value="amitpersonal@demo">Amit Personal · amitpersonal@demo</option>':''}</select></div><div class="button-row"><button type="submit" class="btn">Save & reassess ${icon('refresh')}</button></div></form>`);};
document.addEventListener('submit',async event=>{if(event.target.id!=='backend-edit-form')return;event.preventDefault();if(mutationBusy)return;const data=new FormData(event.target),amount=Number(data.get('amount')),account=data.get('account');if(amount===flow.amount&&account===flow.account){closeModal();return;}try{mutationBusy=true;await updateAction('Recheck required');assessment.invalidated=true;flow.amount=amount;if(account!==flow.account){flow.oldRecipient=flow.recipient;flow.account=account;flow.recipient=account==='sharmamedical@demo'?'Sharma Medical':'Amit Personal';flow.changed=true;}closeModal();}catch(error){toast(error.message);return;}finally{mutationBusy=false;}await analyse();});

const originalOverview=overview;
overview=function(){const metrics=backendMetrics||{};let output=originalOverview();const start=output.indexOf('<div class="metric-grid">'),end=output.indexOf('<div class="chart-grid">',start);if(start>=0&&end>=0)output=output.slice(0,start)+`<div class="metric-grid">${metric('Payments assessed',metrics.total_assessed??0,'Recorded by the backend','transactions')}${metric('Flagged transactions',metrics.flagged_transactions??0,'Suspected indicators · not confirmed fraud','alert')}${metric('Pending reviews',metrics.pending_reviews??0,'Includes cases needing investigation','search')}${metric('Warning rate',metrics.warning_rate??'0%','Median 48 ms · p95 112 ms · illustrative','clock')}</div>`+output.slice(end);output=output.replace('Live within this demo: consumer checks and analyst decisions share the same browser data.','Connected service: consumer checks and analyst decisions use the backend audit store.');output=output.replace('Median 48 ms · p95 112 ms · illustrative',metrics.median_latency_ms==null?'Scoring latency available after your first check':`Median ${esc(metrics.median_latency_ms)} ms · p95 ${esc(metrics.p95_latency_ms)} ms · measured API scoring`);return output;};

const originalInvestigation=investigation;
investigation=function(){const record=state.records.find(r=>r.id===selectedRecord)||state.records.find(r=>r.review==='Pending review')||state.records[0];if(record)selectedRecord=record.id;let output=originalInvestigation();if(!record)return output;const timelineStart=output.indexOf('<section class="card investigation-card"><h2>Evidence timeline</h2>'),timelineEnd=output.indexOf('<section class="card investigation-card"><h2>Decision explanation</h2>',timelineStart);if(timelineStart>=0&&timelineEnd>=0)output=output.slice(0,timelineStart)+`<section class="card investigation-card"><h2>Recorded assessment evidence</h2><p style="font-size:10px;color:var(--muted);margin-bottom:20px">Assessment time: ${dateText(record.time)}. Separate timings for message receipt and warning display were not recorded.</p><ol class="timeline"><li><span class="evidence-tag">Observed · submitted request</span>Supplied demo message<p>“${esc(record.message||'No message supplied.')}”</p><p>${esc(record.account)} · ${money(record.amount)} · outgoing</p></li><li><span class="evidence-tag">Observed · payment details</span>${(record.observed||[]).map(item=>`<p>${esc(item)}</p>`).join('')}</li><li><span class="evidence-tag inferred">Inferred · model interpretation</span>${(record.inferred||[]).map(item=>`<p>${esc(item)}</p>`).join('')||'<p>No interpretation supplied.</p>'}</li><li><span class="evidence-tag unavailable">Unavailable</span>${(record.missing||[]).map(item=>`<p>${esc(item)}</p>`).join('')||'<p>No additional missing signals reported.</p>'}</li><li><span class="evidence-tag">Saved backend state</span>User action: ${esc(record.action)}<p>Analyst review: ${esc(record.review)}</p>${record.invalidated?'<p>Assessment invalidated after details changed.</p>':''}</li></ol></section>`+output.slice(timelineEnd);const contributions=Object.entries(record.featureContributions||{});const start=output.indexOf('<h3 style="font-size:11px;margin-top:20px">Illustrative feature contributions</h3>');const end=output.indexOf('<div class="review-buttons">',start);if(start>=0&&end>=0)output=output.slice(0,start)+`<h3 style="font-size:11px;margin-top:20px">Backend heuristic feature signals</h3>${contributions.map(([label,value])=>`<div class="contribution"><span>${esc(label)}</span><span>${esc(value)}</span><div class="bar"><i style="width:${Math.max(0,Math.min(100,Number(value)))}%"></i></div></div>`).join('')}<div class="model-note"><span class="evidence-tag unavailable">Unavailable</span>${(record.missing||[]).map(esc).join('<br>')||'No additional missing signals reported.'}<br><br>Model: ${esc(record.modelVersion)}<br>Measured scoring latency: ${esc(record.latency)} ms<br>Feature signals are heuristic weights supplied by the backend, not SHAP values or causal attributions.</div>`+output.slice(end);return output;};

patterns=function(){return `${analystHead('Find the pattern behind the payment.','Explore backend cases and compare the supplied trained candidate.')}<div class="evaluation-note">Candidate preparation selects the existing trained artifact. No retraining or automatic deployment is performed by this workflow.</div><div class="cluster-grid"><section class="card cluster featured"><span class="pill medium">Held-out family</span><h2>Refundable job-onboarding deposit</h2><p>Review the supplied messages, observed payment details, and unavailable identity evidence before adding an analyst label.</p><div class="cluster-meta"><span>Refundable deposit</span><span>New recipient</span><span>Job offer</span></div><strong>${state.records.filter(r=>r.scenario==='job').length} backend case(s)</strong><div class="assessment-actions">${btn('Review examples','pattern-examples','full')}${btn('Prepare candidate comparison','prepare-candidate','secondary full')}</div></section><section class="card cluster"><span class="pill high">Intent contradiction</span><h2>Refund language, outgoing payments</h2><p>A supplied message may promise incoming money while the observed payment sends money.</p><div class="assessment-actions">${btn('Explore refund cases','refund-cases','secondary full')}</div></section><section class="card cluster"><span class="pill high">Recipient evidence</span><h2>Shop QR, different destination</h2><p>Compare the QR account with the independent synthetic merchant registry loaded by the backend.</p><div class="assessment-actions">${btn('Explore QR cases','qr-cases','secondary full')}</div></section></div><div class="button-row">${btn('Compare evaluation','compare-evaluation','','chart')}</div>${footer()}`;};

evaluation=function(){const result=backendEvaluation;if(!result)return `${analystHead('Model evaluation','Evaluation results are currently unavailable.')}<div class="card empty">${icon('info')}<p>The backend has not returned an evaluation artifact.</p>${btn('Retry','retry-backend','secondary')}</div>`;const m=result.overall_metrics||{},abl=result.ablation_study||{},cm=result.confusion_matrix||{},adapt=result.pattern_lab_adaptation||{},pct=v=>Number.isFinite(v)?v.toFixed(2)+'%':'Unavailable',decimal=v=>Number.isFinite(v)?v.toFixed(4):'Unavailable';const rows=[['Precision',pct(abl.rules_only?.precision),pct(abl.transaction_only?.precision),pct(m.precision)],['Recall',pct(abl.rules_only?.recall),pct(abl.transaction_only?.recall),pct(m.recall)],['False-positive rate',pct(abl.rules_only?.fpr),pct(abl.transaction_only?.fpr),pct(m.false_positive_rate)],['PR-AUC','Unavailable','Unavailable',decimal(m.pr_auc)],['Median scoring latency','Unavailable','Unavailable',m.median_latency_ms+' ms'],['p95 scoring latency','Unavailable','Unavailable',m.p95_latency_ms+' ms']];return `${analystHead('Evaluate the whole picture.','Results loaded from your backend evaluation artifact.')}<div class="evaluation-note"><strong>Supplied offline evaluation · synthetic dataset.</strong> ${esc(result.provenance)} ${esc(result.scope)}<br>Test set: ${Number(result.dataset?.test_transactions||0).toLocaleString('en-IN')} · Fraud prevalence: ${pct(result.dataset?.fraud_prevalence_pct)} · Artifact timestamp: ${esc(result.timestamp)} · Hardware: ${esc(result.hardware)}</div><div class="card table-scroll"><table class="eval-table"><thead><tr><th>Metric</th><th>Rules-only baseline</th><th>Transaction-only model</th><th>Full hybrid system</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map((value,i)=>`<${i?'td':'th'}>${esc(value)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><div class="eval-bottom"><section class="card chart-card"><h2>Per-category recall</h2><p style="font-size:10px;color:var(--muted);margin-top:8px">From the supplied offline artifact</p>${Object.entries(result.per_scam_recall||{}).map(([label,value])=>`<div class="contribution"><span>${esc(label.replaceAll('_',' '))}</span><span>${pct(value)}</span><div class="bar"><i style="width:${Math.max(0,Math.min(100,value))}%"></i></div></div>`).join('')}</section><section class="card chart-card"><h2>Confusion matrix</h2><div class="matrix">${[['True positives',cm.true_positives],['False positives',cm.false_positives],['False negatives',cm.false_negatives],['True negatives',cm.true_negatives]].map(([label,value])=>`<div><strong>${esc(value)}</strong><small>${label}</small></div>`).join('')}</div></section></div><section class="card form-card" style="margin-top:22px"><h2>Held-out onboarding-deposit family</h2><p style="font-size:11px;color:var(--muted);margin:12px 0">The supplied artifact reports original recall ${pct(adapt.original_recall)} and candidate recall ${pct(adapt.candidate_recall)}. These values show ${adapt.candidate_recall>adapt.original_recall?'an increase':'no increase'} in reported recall. Family test-set size and full candidate metrics were not supplied.</p><div class="info-note">${icon('info')}${state.candidate==='prepared'?'Existing candidate selected for comparison. No new training or deployment occurred.':'Review a case in Pattern Lab to select the existing candidate for comparison.'}</div></section>${footer()}`;};

const originalSettings=settings;
settings=function(){return originalSettings().replace('Demo records and preferences are stored in this browser. No real AI model or bank connection is used.','Supplied demo payment details are sent to the connected trained-model service. Assessment records and analyst decisions are saved in its audit database. Display preferences stay in this browser. No live bank connection is used.').replace('डेमो रिकॉर्ड इसी ब्राउज़र में सेव रहते हैं। कोई वास्तविक AI मॉडल या बैंक कनेक्शन नहीं है।','डेमो विवरण जुड़े हुए मॉडल सर्वर पर भेजे जाते हैं। जाँच और विश्लेषक फैसले सर्वर पर सेव रहते हैं। कोई लाइव बैंक कनेक्शन नहीं है।').replace('Restore the original sample checks, preferences, and candidate-model state.','Clear checks and analyst decisions for the current backend demo workspace.').replace('मूल डेमो जाँच, पसंद और मॉडल की स्थिति वापस लाएँ।','इस सर्वर डेमो कार्यक्षेत्र की जाँच और फैसले हटाएँ।');};
const originalHome=home;
home=function(){return originalHome().replace('Only information you choose to share in this demo is analysed. Your other apps stay private.','Only demo details you choose to submit are sent to the payment-check service. Your other apps stay private.');};
const originalActivity=activity;
activity=function(){return originalActivity().replace('Saved only in this browser. Reset your demo data in Settings.','Checks and decisions are saved in the backend audit store. Reset this workspace in Settings.').replace('केवल इस ब्राउज़र में सेव। सेटिंग्स से डेमो डेटा रीसेट करें।','जाँच और फैसले सर्वर पर सेव हैं। सेटिंग्स से कार्यक्षेत्र रीसेट करें।');};

// Server records are authoritative; do not fabricate sample records on connection failure.
state.records=[];state.candidate='none';render();refreshBackend();
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!mutationBusy)refreshBackend(false).then(()=>{if(['home','activity','overview','transactions','investigations','evaluation','patterns'].includes(page))render();});});
